B.a1d=new A.c2("Je rassemble la ligue\u2026",80,null)
B.a1e=new A.c2("Je pr\xe9pare les listes\u2026",60,null)
B.a1f=new A.c2("Je fouille les \xe9tag\xe8res\u2026",80,null)
B.a1g=new A.c2("Personne n'a encore rien vu ce mois-ci. Le premier qui joue une carte donne le ton !",60,null)
B.a1h=new A.c2("Je rembobine la pellicule\u2026",80,null)
